Q: How To Connect to adb via WiFi *With a convenient BAT file* A: <pre><code>#!/bin/zsh
# Double-click this file in Finder (like a .bat on Windows).
# One-time setup on Mac:  chmod +x ~/Desktop/adb_wifi_connect.command

# Finder sometimes runs .command via bash - force native zsh
if [ -z &quot;${ZSH_VERSION:-}&quot; ]; then
  exec /bin/zsh &quot;$0&quot; &quot;$@&quot;
fi

setopt ERR_EXIT NO_UNSET PIPE_FAIL
setopt KSH_ARRAYS

# Finder double-click does not load ~/.zprofile - add common adb locations
export PATH=&quot;/opt/homebrew/bin:/usr/local/bin:${HOME}/Library/Android/sdk/platform-tools:${HOME}/Android/Sdk/platform-tools:${PATH}&quot;

# zsh read-only/special names to NEVER use as variables:
# status path pwd PWD pipestatus reply history options functions parameters
# widgets modules builtins commands aliases watch signals prompts argv

DEFAULT_PORT=5555
SESSION_ERROR=0

SCRIPT_DIR=&quot;${0:A:h}&quot;
SAVED_FILE=&quot;${SCRIPT_DIR}/adb_wifi_saved.txt&quot;

ensure_adb() {
  command -v adb &gt;/dev/null 2&gt;&amp;1 &amp;&amp; return 0
  local adb_path
  for adb_path in \
    /opt/homebrew/bin/adb \
    /usr/local/bin/adb \
    &quot;${HOME}/Library/Android/sdk/platform-tools/adb&quot; \
    &quot;${HOME}/Android/Sdk/platform-tools/adb&quot;
  do
    if [[ -x &quot;$adb_path&quot; ]]; then
      export PATH=&quot;${adb_path:h}:${PATH}&quot;
      return 0
    fi
  done
  return 1
}

pause_before_close() {
  print
  read -r &quot;?Press Enter to close...&quot;
}

# Parse one &quot;adb devices&quot; line (zsh-safe; never use variable name &quot;status&quot;)
parse_adb_device_line() {
  local adb_line=&quot;$1&quot;
  PARSED_SERIAL=&quot;${adb_line%%[[:space:]]*}&quot;
  PARSED_STATE=&quot;${adb_line#*$PARSED_SERIAL}&quot;
  PARSED_STATE=&quot;${PARSED_STATE#${PARSED_STATE%%[![:space:]]*}}&quot;
}

clean_adb_value() {
  local v=&quot;$1&quot;
  v=&quot;${v//[$'\r\n\t ']}&quot;
  v=&quot;${v//[\&quot;\'\[\]]/}&quot;
  print -r -- &quot;$v&quot;
}

strip_cidr() {
  print -r -- &quot;${1%%/*}&quot;
}

extract_first_ipv4() {
  if [[ &quot;$1&quot; =~ '([0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3})' ]]; then
    print -r -- &quot;$match[1]&quot;
  fi
}

is_private_ip() {
  [[ &quot;$1&quot; =~ '^10\.' ]] &amp;&amp; return 0
  [[ &quot;$1&quot; =~ '^192\.168\.' ]] &amp;&amp; return 0
  [[ &quot;$1&quot; =~ '^172\.(1[6-9]|2[0-9]|3[0-1])\.' ]] &amp;&amp; return 0
  return 1
}

# Trim spaces; allow user to paste 192.168.1.5:5555
normalize_ip_input() {
  local v=&quot;${1//[$'\r\n\t ']/}&quot;
  if [[ &quot;$v&quot; =~ '^([0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}):([0-9]+)$' ]]; then
    v=&quot;$match[1]&quot;
  fi
  print -r -- &quot;$v&quot;
}

is_valid_ip() {
  local ip o
  ip=&quot;$(normalize_ip_input &quot;$1&quot;)&quot;
  [[ &quot;$ip&quot; =~ '^([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$' ]] || return 1
  for o in &quot;$match[1]&quot; &quot;$match[2]&quot; &quot;$match[3]&quot; &quot;$match[4]&quot;; do
    [[ &quot;$o&quot; =~ '^[0-9]+$' ]] || return 1
    # 10# forces decimal - avoids zsh &quot;bad base syntax&quot; on 008, 009, etc.
    (( 10#$o &gt;= 0 &amp;&amp; 10#$o &lt;= 255 )) || return 1
  done
  return 0
}

is_valid_port() {
  [[ &quot;$1&quot; =~ '^[0-9]+$' ]] || return 1
  (( 10#$1 &gt;= 1 &amp;&amp; 10#$1 &lt;= 65535 ))
}

accept_wifi_ip() {
  [[ -n &quot;$1&quot; ]] &amp;&amp; is_valid_ip &quot;$1&quot; &amp;&amp; is_private_ip &quot;$1&quot;
}

adb_shell() {
  local serial=&quot;$1&quot;
  shift
  { adb -s &quot;$serial&quot; shell &quot;$@&quot; 2&gt;/dev/null || true; } | tr -d '\r'
}

adb_device_ready() {
  local serial=&quot;$1&quot;
  adb -s &quot;$serial&quot; get-state 2&gt;/dev/null | grep -q '^device$'
}

list_net_ifaces() {
  local serial=&quot;$1&quot; iface
  while IFS= read -r iface || [[ -n &quot;$iface&quot; ]]; do
    iface=&quot;${iface//[$'\r\n']/}&quot;
    [[ -n &quot;$iface&quot; ]] &amp;&amp; print -r -- &quot;$iface&quot;
  done &lt; &lt;(adb_shell &quot;$serial&quot; ls /sys/class/net/ || true)
}

try_get_prop() {
  local serial=&quot;$1&quot; prop=&quot;$2&quot; val
  val=&quot;$(adb_shell &quot;$serial&quot; getprop &quot;$prop&quot; | tr -d '\n' || true)&quot;
  val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
  if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  return 1
}

try_getprop_scan() {
  local serial=&quot;$1&quot; line val
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    val=&quot;$(extract_first_ipv4 &quot;$line&quot;)&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done &lt; &lt;(adb_shell &quot;$serial&quot; getprop | grep -iE 'ipaddress|wifi.*ip|wlan.*ip' || true)
  return 1
}

try_discovered_ifaces() {
  local serial=&quot;$1&quot; iface ip
  local -a ifaces=()

  while IFS= read -r iface || [[ -n &quot;$iface&quot; ]]; do
    iface=&quot;${iface//[$'\r\n']/}&quot;
    [[ -n &quot;$iface&quot; ]] &amp;&amp; ifaces+=(&quot;$iface&quot;)
  done &lt; &lt;(list_net_ifaces &quot;$serial&quot;)

  for iface in &quot;${ifaces[@]}&quot;; do
    [[ &quot;$iface&quot; == &quot;lo&quot; ]] &amp;&amp; continue
    [[ &quot;$iface&quot; == wlan* || &quot;$iface&quot; == *wlan* || &quot;$iface&quot; == wifi* || &quot;$iface&quot; == swlan* ]] || continue
    ip=&quot;$(try_wlan_inet &quot;$serial&quot; &quot;$iface&quot; 2&gt;/dev/null || true)&quot;
    if accept_wifi_ip &quot;$ip&quot;; then print -r -- &quot;$ip&quot;; return 0; fi
  done

  for iface in &quot;${ifaces[@]}&quot;; do
    [[ &quot;$iface&quot; == &quot;lo&quot; ]] &amp;&amp; continue
    [[ &quot;$iface&quot; == wlan* || &quot;$iface&quot; == *wlan* || &quot;$iface&quot; == wifi* || &quot;$iface&quot; == swlan* ]] &amp;&amp; continue
    [[ &quot;$iface&quot; == rmnet* || &quot;$iface&quot; == dummy* || &quot;$iface&quot; == tun* || &quot;$iface&quot; == ifb* ]] &amp;&amp; continue
    ip=&quot;$(try_wlan_inet &quot;$serial&quot; &quot;$iface&quot; 2&gt;/dev/null || true)&quot;
    if accept_wifi_ip &quot;$ip&quot;; then print -r -- &quot;$ip&quot;; return 0; fi
  done
  return 1
}

try_ip_addr_global() {
  local serial=&quot;$1&quot; line val iface
  # Pass 1: wlan interfaces only
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    iface=&quot;$(print -r -- &quot;$line&quot; | awk '{print $2}')&quot;
    [[ &quot;$iface&quot; != wlan* ]] &amp;&amp; continue
    val=&quot;$(print -r -- &quot;$line&quot; | awk '{print $4}')&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done &lt; &lt;(adb_shell &quot;$serial&quot; ip -o -4 addr show || true)
  # Pass 2: any non-loopback interface
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    [[ &quot;$line&quot; == *&quot; lo &quot;* || &quot;$line&quot; == &quot;1: lo&quot;* ]] &amp;&amp; continue
    val=&quot;$(print -r -- &quot;$line&quot; | awk '{print $4}')&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done &lt; &lt;(adb_shell &quot;$serial&quot; ip -o -4 addr show || true)
  return 1
}

try_route_src() {
  local serial=&quot;$1&quot; dest line word prev=&quot;&quot;
  for dest in 1.1.1.1 8.8.8.8 9.9.9.9; do
    while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
      line=&quot;${line//$'\r'/}&quot;
      prev=&quot;&quot;
      for word in ${=line}; do
        word=&quot;${word#${word%%[![:space:]]*}}&quot;
        word=&quot;${word%${word##*[![:space:]]}}&quot;
        word=&quot;${word%%/*}&quot;
        [[ -z &quot;$word&quot; ]] &amp;&amp; continue
        if [[ &quot;$prev&quot; == &quot;src&quot; || &quot;$prev&quot; == &quot;from&quot; ]] &amp;&amp; accept_wifi_ip &quot;$word&quot;; then
          print -r -- &quot;$word&quot;
          return 0
        fi
        prev=&quot;$word&quot;
      done
    done &lt; &lt;(adb_shell &quot;$serial&quot; ip -4 route get &quot;$dest&quot; || true)
  done
  return 1
}

try_dumpsys_wifi() {
  local serial=&quot;$1&quot; line val
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    val=&quot;$(extract_first_ipv4 &quot;$line&quot;)&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done &lt; &lt;(adb_shell &quot;$serial&quot; dumpsys wifi | grep -iE 'ipaddress|ip_address|linkaddress|wifi.*ip|mIpAddress|assigned|linkproperties' || true)
  return 1
}

try_dumpsys_connectivity() {
  local serial=&quot;$1&quot; line val
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    val=&quot;$(extract_first_ipv4 &quot;$line&quot;)&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done &lt; &lt;(adb_shell &quot;$serial&quot; dumpsys connectivity | grep -iE 'LinkAddress|InetAddress|Wifi|wlan|Stack' || true)
  return 1
}

try_wlan_inet() {
  local serial=&quot;$1&quot; iface=&quot;$2&quot; line val
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    [[ &quot;$line&quot; != *&quot;inet &quot;* ]] &amp;&amp; continue
    val=&quot;$(print -r -- &quot;$line&quot; | awk '{print $2}')&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done &lt; &lt;(adb_shell &quot;$serial&quot; ip -4 addr show &quot;$iface&quot; || true)
  return 1
}

try_ifconfig() {
  local serial=&quot;$1&quot; iface out val
  for iface in wlan0 wlan1 eth0 wifi0; do
    out=&quot;$(adb_shell &quot;$serial&quot; ifconfig &quot;$iface&quot; || true)&quot;
    val=&quot;$(extract_first_ipv4 &quot;$out&quot;)&quot;
    val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
    if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  done
  return 1
}

try_cmd_wifi() {
  local serial=&quot;$1&quot; out val
  out=&quot;$(adb_shell &quot;$serial&quot; cmd wifi status || true)&quot;
  val=&quot;$(extract_first_ipv4 &quot;$out&quot;)&quot;
  val=&quot;$(strip_cidr &quot;$(clean_adb_value &quot;$val&quot;)&quot;)&quot;
  if accept_wifi_ip &quot;$val&quot;; then print -r -- &quot;$val&quot;; return 0; fi
  return 1
}

try_all_wlan_ifaces() {
  local serial=&quot;$1&quot; iface ip
  for iface in wlan0 wlan1 eth0 wifi0 swlan0 p2p0; do
    ip=&quot;$(try_wlan_inet &quot;$serial&quot; &quot;$iface&quot; 2&gt;/dev/null || true)&quot;
    if accept_wifi_ip &quot;$ip&quot;; then print -r -- &quot;$ip&quot;; return 0; fi
  done
  return 1
}

print_ip_diagnostics() {
  local serial=&quot;$1&quot;
  local line val found=0 ifaces

  print -r -- &quot;[INFO] Network snapshot from device:&quot;

  ifaces=&quot;$(list_net_ifaces &quot;$serial&quot; | tr '\n' ' ')&quot;
  [[ -n &quot;$ifaces&quot; ]] &amp;&amp; print -r -- &quot;       interfaces: ${ifaces}&quot;

  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    [[ &quot;$line&quot; == *&quot; lo &quot;* || &quot;$line&quot; == *&quot;: lo&quot;* ]] &amp;&amp; continue
    [[ &quot;$line&quot; != *&quot;inet &quot;* &amp;&amp; &quot;$line&quot; != *&quot;:&quot;* ]] &amp;&amp; continue
    val=&quot;$(extract_first_ipv4 &quot;$line&quot;)&quot;
    [[ -z &quot;$val&quot; ]] &amp;&amp; continue
    print -r -- &quot;       $line&quot;
    found=1
  done &lt; &lt;(adb_shell &quot;$serial&quot; ip -4 addr show || true)

  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    val=&quot;$(extract_first_ipv4 &quot;$line&quot;)&quot;
    [[ -z &quot;$val&quot; ]] &amp;&amp; continue
    print -r -- &quot;       getprop: $line&quot;
    found=1
  done &lt; &lt;(adb_shell &quot;$serial&quot; getprop | grep -i ipaddress | head -5 || true)

  if (( found == 0 )); then
    print -r -- &quot;       (no IPv4 found - unlock phone, confirm Wi-Fi is connected)&quot;
  fi

  print -r -- &quot;       Tip: Settings &gt; Wi-Fi &gt; your network &gt; view IP, then enter manually.&quot;
}

get_wifi_ip() {
  local serial=&quot;$1&quot; ip=&quot;&quot;

  if ! adb_device_ready &quot;$serial&quot;; then
    return 1
  fi

  local -a prop_keys=(
    dhcp.wlan0.ipaddress
    dhcp.wlan1.ipaddress
    dhcp.eth0.ipaddress
    dhcp.vendor.wlan0.ipaddress
    persist.sys.wlan0.ipaddress
  )
  local prop
  for prop in &quot;${prop_keys[@]}&quot;; do
    ip=&quot;$(try_get_prop &quot;$serial&quot; &quot;$prop&quot; 2&gt;/dev/null || true)&quot;
    if accept_wifi_ip &quot;$ip&quot;; then print -r -- &quot;$ip&quot;; return 0; fi
  done

  ip=&quot;$(try_discovered_ifaces &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_getprop_scan &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_all_wlan_ifaces &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_ip_addr_global &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_route_src &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_dumpsys_connectivity &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_dumpsys_wifi &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_ifconfig &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }
  ip=&quot;$(try_cmd_wifi &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; { print -r -- &quot;$ip&quot;; return 0; }

  return 1
}

save_device_record() {
  local rec_ip=&quot;$1&quot; rec_port=&quot;${2:-$DEFAULT_PORT}&quot; rec_label=&quot;${3:--}&quot; rec_serial=&quot;${4:--}&quot;
  local tmpfile file_line sip spt

  # Pipe is the field delimiter - strip it from labels to keep parsing safe
  rec_label=&quot;${rec_label//|/_}&quot;
  rec_serial=&quot;${rec_serial//|/_}&quot;

  if [[ ! -f &quot;$SAVED_FILE&quot; ]]; then
    print -r -- &quot;${rec_ip}|${rec_port}|${rec_label}|${rec_serial}&quot; &gt;&gt; &quot;$SAVED_FILE&quot;
    print -r -- &quot;[OK] Saved to $SAVED_FILE&quot;
    return 0
  fi

  tmpfile=&quot;$(mktemp &quot;${TMPDIR:-/tmp}/adb_wifi_saved.XXXXXX&quot;)&quot;
  while IFS= read -r file_line || [[ -n &quot;$file_line&quot; ]]; do
    [[ -z &quot;$file_line&quot; ]] &amp;&amp; continue
    sip=&quot;${file_line%%|*}&quot;
    spt=&quot;${file_line#*|}&quot;; spt=&quot;${spt%%|*}&quot;
    if [[ &quot;${(L)sip}&quot; == &quot;${(L)rec_ip}&quot; &amp;&amp; &quot;$spt&quot; == &quot;$rec_port&quot; ]]; then
      continue
    fi
    print -r -- &quot;$file_line&quot; &gt;&gt; &quot;$tmpfile&quot;
  done &lt; &quot;$SAVED_FILE&quot;

  print -r -- &quot;${rec_ip}|${rec_port}|${rec_label}|${rec_serial}&quot; &gt;&gt; &quot;$tmpfile&quot;
  mv &quot;$tmpfile&quot; &quot;$SAVED_FILE&quot;
  print -r -- &quot;[OK] Saved to $SAVED_FILE&quot;
}

load_saved_list() {
  typeset -g SCOUNT=0
  typeset -ga SIP=() SPT=() SLB=() SSR=()

  [[ ! -f &quot;$SAVED_FILE&quot; ]] &amp;&amp; return 0

  local line a b c d
  while IFS= read -r line || [[ -n &quot;$line&quot; ]]; do
    [[ -z &quot;$line&quot; ]] &amp;&amp; continue
    a=&quot;${line%%|*}&quot;
    b=&quot;${line#*|}&quot;; b=&quot;${b%%|*}&quot;
    c=&quot;${line#*|}&quot;; c=&quot;${c#*|}&quot;; c=&quot;${c%%|*}&quot;
    d=&quot;${line##*|}&quot;
    if ! is_valid_ip &quot;$a&quot; || ! is_valid_port &quot;${b:-$DEFAULT_PORT}&quot;; then
      print -r -- &quot;[WARN] Skipping invalid saved entry: $line&quot;
      continue
    fi
    (( ++SCOUNT ))
    SIP+=(&quot;$a&quot;)
    SPT+=(&quot;${b:-$DEFAULT_PORT}&quot;)
    SLB+=(&quot;${c:--}&quot;)
    SSR+=(&quot;${d:--}&quot;)
  done &lt; &quot;$SAVED_FILE&quot;
}

delete_saved_entry() {
  local dn=&quot;$1&quot;
  if [[ -z &quot;$dn&quot; ]]; then
    print -r -- &quot;[ERROR] No number given.&quot;
    return 0
  fi
  if [[ ! &quot;$dn&quot; =~ '^[0-9]+$' ]]; then
    print -r -- &quot;[ERROR] Invalid number: $dn&quot;
    return 0
  fi
  [[ ! -f &quot;$SAVED_FILE&quot; ]] &amp;&amp; return 0

  local tmpfile idx=0 max=0 file_line
  tmpfile=&quot;$(mktemp &quot;${TMPDIR:-/tmp}/adb_wifi_del.XXXXXX&quot;)&quot;

  while IFS= read -r file_line || [[ -n &quot;$file_line&quot; ]]; do
    [[ -z &quot;$file_line&quot; ]] &amp;&amp; continue
    (( ++max ))
  done &lt; &quot;$SAVED_FILE&quot;

  if (( dn &lt; 1 || dn &gt; max )); then
    rm -f &quot;$tmpfile&quot;
    print -r -- &quot;[ERROR] No entry number $dn (have $max).&quot;
    return 0
  fi

  while IFS= read -r file_line || [[ -n &quot;$file_line&quot; ]]; do
    [[ -z &quot;$file_line&quot; ]] &amp;&amp; continue
    (( ++idx ))
    [[ &quot;$idx&quot; -eq &quot;$dn&quot; ]] &amp;&amp; continue
    print -r -- &quot;$file_line&quot; &gt;&gt; &quot;$tmpfile&quot;
  done &lt; &quot;$SAVED_FILE&quot;

  mv &quot;$tmpfile&quot; &quot;$SAVED_FILE&quot;
  print -r -- &quot;[OK] Removed entry $dn&quot;
}

direct_connect() {
  local dip=&quot;$1&quot; dport=&quot;${2:-$DEFAULT_PORT}&quot;
  if ! is_valid_ip &quot;$dip&quot;; then
    print -r -- &quot;[ERROR] Invalid IP: $dip&quot;
    SESSION_ERROR=1
    return 0
  fi
  if ! is_valid_port &quot;$dport&quot;; then
    print -r -- &quot;[ERROR] Invalid port: $dport&quot;
    SESSION_ERROR=1
    return 0
  fi
  print -r -- &quot;[STEP] adb connect ${dip}:${dport}&quot;
  if adb connect &quot;${dip}:${dport}&quot;; then
    print -r -- &quot;[OK] Connected ${dip}:${dport}&quot;
  else
    print -r -- &quot;[ERROR] connect failed: ${dip}:${dport}&quot;
    print -r -- &quot;        Same Wi-Fi? Wireless debugging on? IP changed?&quot;
    print -r -- &quot;        Try [C] with USB if phone was rebooted.&quot;
    SESSION_ERROR=1
  fi
}

connect_one_device() {
  local serial=&quot;$1&quot; tcp_port=&quot;$2&quot; ip=&quot;&quot; useip saveit label useip_lc

  print -r -- &quot;============================================&quot;
  print -r -- &quot;Device: $serial&quot;
  print -r -- &quot;============================================&quot;

  if ! adb_device_ready &quot;$serial&quot;; then
    print -r -- &quot;[ERROR] Device not ready: $serial&quot;
    print -r -- &quot;        Unlock phone and accept USB debugging prompt.&quot;
    SESSION_ERROR=1
    print
    return 0
  fi

  useip=&quot;&quot;
  if ip=&quot;$(get_wifi_ip &quot;$serial&quot; 2&gt;/dev/null || true)&quot; &amp;&amp; accept_wifi_ip &quot;$ip&quot;; then
    print -r -- &quot;[OK] Auto-detected IP: $ip&quot;
    read -r &quot;useip?Use this IP? [Y/n] or type new IP: &quot;
  else
    print -r -- &quot;[WARN] Could not auto-detect valid IP.&quot;
    print -r -- &quot;       - Phone unlocked? (locked screen may block shell)&quot;
    print -r -- &quot;       - Wi-Fi connected (not mobile data only)&quot;
    print -r -- &quot;       - Phone and Mac on same network&quot;
    print_ip_diagnostics &quot;$serial&quot;
    print
    ip=&quot;&quot;
    read -r &quot;ip?Enter IP manually (Enter=skip): &quot;
  fi

  if [[ -n &quot;$useip&quot; ]]; then
    useip_lc=&quot;${(L)useip}&quot;
    if [[ &quot;$useip_lc&quot; == &quot;n&quot; ]]; then
      read -r &quot;ip?Enter IP: &quot;
    elif [[ &quot;$useip_lc&quot; != &quot;y&quot; ]]; then
      ip=&quot;$useip&quot;
    fi
  fi

  ip=&quot;$(normalize_ip_input &quot;$ip&quot;)&quot;

  if ! is_valid_ip &quot;$ip&quot;; then
    print -r -- &quot;[SKIP] No valid IP for $serial (need x.x.x.x, usually 192.168.x.x)&quot;
    SESSION_ERROR=1
    print
    return 0
  fi

  print
  print -r -- &quot;[STEP] adb -s $serial tcpip $tcp_port&quot;
  if ! adb -s &quot;$serial&quot; tcpip &quot;$tcp_port&quot;; then
    print -r -- &quot;[ERROR] tcpip failed for $serial&quot;
    print -r -- &quot;        USB connected? Debugging allowed? Phone unlocked?&quot;
    print -r -- &quot;        Android 11+: use USB once, or enable Wireless debugging.&quot;
    SESSION_ERROR=1
    print
    return 0
  fi
  print -r -- &quot;[OK] tcpip enabled on port $tcp_port&quot;

  sleep 2

  print -r -- &quot;[STEP] adb connect ${ip}:${tcp_port}&quot;
  if ! adb connect &quot;${ip}:${tcp_port}&quot;; then
    print -r -- &quot;[ERROR] connect failed for ${ip}:${tcp_port}&quot;
    SESSION_ERROR=1
    print
    return 0
  fi
  print -r -- &quot;[OK] adb connect ${ip}:${tcp_port}&quot;

  adb -s &quot;${ip}:${tcp_port}&quot; get-state 2&gt;/dev/null | grep -q '^device$' || {
    print -r -- &quot;[WARN] Connected but device not showing as 'device' yet.&quot;
    print -r -- &quot;       Wait a few seconds, then check [L] List devices.&quot;
  }

  read -r &quot;saveit?Save this IP for next time (no USB)? [Y/n]: &quot;
  if [[ -z &quot;$saveit&quot; || &quot;${(L)saveit}&quot; != &quot;n&quot; ]]; then
    read -r &quot;label?Friendly name (Enter=serial): &quot;
    label=&quot;${label:-$serial}&quot;
    save_device_record &quot;$ip&quot; &quot;$tcp_port&quot; &quot;$label&quot; &quot;$serial&quot;
  fi
  print
}

run_connect() {
  local -a devs=() dev_stats=() selected=()
  local adb_line dev_serial dev_state count=0 wifi_only=0 choice choice_lc tcp_port n i

  while IFS= read -r adb_line || [[ -n &quot;$adb_line&quot; ]]; do
    parse_adb_device_line &quot;$adb_line&quot;
    dev_serial=&quot;$PARSED_SERIAL&quot;
    dev_state=&quot;$PARSED_STATE&quot;
    [[ -z &quot;$dev_serial&quot; ]] &amp;&amp; continue
    [[ &quot;$dev_state&quot; == &quot;offline&quot; || &quot;$dev_state&quot; == &quot;unauthorized&quot; ]] &amp;&amp; continue
    if [[ &quot;$dev_serial&quot; == *:* ]]; then
      (( ++wifi_only ))
      continue
    fi
    devs+=(&quot;$dev_serial&quot;)
    dev_stats+=(&quot;$dev_state&quot;)
    (( ++count ))
  done &lt; &lt;(adb devices 2&gt;/dev/null | tail -n +2)

  if [[ $count -eq 0 ]]; then
    print -r -- &quot;[ERROR] No USB device found.&quot;
    if (( wifi_only &gt; 0 )); then
      print -r -- &quot;        Wi-Fi device(s) already listed - use [S] saved connect instead.&quot;
    fi
    print -r -- &quot;        - Connect USB and enable USB debugging&quot;
    print -r -- &quot;        - Accept RSA prompt on phone&quot;
    SESSION_ERROR=1
    return 0
  fi

  print
  print -r -- &quot;Select device to connect:&quot;
  for (( i = 0; i &lt; count; i++ )); do
    print -r -- &quot;  [$(( i + 1 ))] ${devs[i]}  (${dev_stats[i]})&quot;
  done
  print -r -- &quot;  [A] All devices&quot;
  print -r -- &quot;  [B] Back (no connect)&quot;
  print
  read -r &quot;choice?Enter number, A, or B: &quot;
  choice_lc=&quot;${(L)choice}&quot;
  [[ &quot;$choice_lc&quot; == &quot;b&quot; ]] &amp;&amp; return 0

  if [[ &quot;$choice_lc&quot; == &quot;a&quot; ]]; then
    for (( i = 1; i &lt;= count; i++ )); do selected+=(&quot;$i&quot;); done
  else
    for n in ${=choice}; do
      if [[ &quot;$n&quot; =~ '^[0-9]+$' ]] &amp;&amp; (( n &gt;= 1 &amp;&amp; n &lt;= count )); then
        selected+=(&quot;$n&quot;)
      else
        print -r -- &quot;[ERROR] Invalid selection: $n&quot;
        SESSION_ERROR=1
        return 0
      fi
    done
  fi

  if [[ ${#selected[@]} -eq 0 ]]; then
    print -r -- &quot;[ERROR] Nothing selected.&quot;
    SESSION_ERROR=1
    return 0
  fi

  read -r &quot;tcp_port?TCP port [default $DEFAULT_PORT]: &quot;
  tcp_port=&quot;${tcp_port:-$DEFAULT_PORT}&quot;
  if ! is_valid_port &quot;$tcp_port&quot;; then
    print -r -- &quot;[ERROR] Invalid port: $tcp_port (use 1-65535)&quot;
    SESSION_ERROR=1
    return 0
  fi

  print
  print -r -- &quot;Note: Wi-Fi ON on phone. USB required for adb tcpip step.&quot;
  print -r -- &quot;      Phone and Mac should be on same network for connect.&quot;
  print -r -- &quot;      Android 11+: first-time setup needs USB or Wireless debugging.&quot;
  print

  for n in &quot;${selected[@]}&quot;; do
    connect_one_device &quot;${devs[$(( n - 1 ))]}&quot; &quot;$tcp_port&quot;
  done

  print
  print -r -- &quot;=== Devices after connect ===&quot;
  adb devices -l || { print -r -- &quot;[ERROR] adb devices -l failed.&quot;; SESSION_ERROR=1; }

  if [[ &quot;$SESSION_ERROR&quot; == &quot;1&quot; ]]; then
    print; print -r -- &quot;[SUMMARY] Connect finished with errors.&quot;
  else
    print; print -r -- &quot;[SUMMARY] Connect finished successfully.&quot;
  fi
}

connect_from_saved() {
  local schoice schoice_lc i

  print
  load_saved_list
  if [[ $SCOUNT -eq 0 ]]; then
    print -r -- &quot;[INFO] No saved devices.&quot;
    print -r -- &quot;       Use [C] with USB once, then save when prompted.&quot;
    print -r -- &quot;       File: $SAVED_FILE&quot;
    return 0
  fi

  print -r -- &quot;=== Saved devices (direct adb connect, no USB) ===&quot;
  for (( i = 0; i &lt; SCOUNT; i++ )); do
    print -r -- &quot;  [$(( i + 1 ))] ${SLB[i]}  ${SIP[i]}:${SPT[i]}  (serial: ${SSR[i]})&quot;
  done
  print -r -- &quot;  [A] Connect ALL saved&quot;
  print -r -- &quot;  [B] Back&quot;
  print
  read -r &quot;schoice?Select number, A, or B: &quot;
  schoice_lc=&quot;${(L)schoice}&quot;
  [[ &quot;$schoice_lc&quot; == &quot;b&quot; ]] &amp;&amp; return 0

  if [[ &quot;$schoice_lc&quot; == &quot;a&quot; ]]; then
    for (( i = 0; i &lt; SCOUNT; i++ )); do
      direct_connect &quot;${SIP[i]}&quot; &quot;${SPT[i]}&quot;
    done
  elif [[ &quot;$schoice&quot; =~ '^[0-9]+$' ]] &amp;&amp; (( schoice &gt;= 1 &amp;&amp; schoice &lt;= SCOUNT )); then
    direct_connect &quot;${SIP[$(( schoice - 1 ))]}&quot; &quot;${SPT[$(( schoice - 1 ))]}&quot;
  else
    print -r -- &quot;[ERROR] Invalid selection: $schoice&quot;
    SESSION_ERROR=1
  fi

  print
  print -r -- &quot;=== Devices after connect ===&quot;
  adb devices -l || print -r -- &quot;[ERROR] adb devices -l failed.&quot;
}

disconnect_manual() {
  local dip dport
  read -r &quot;dip?IP address: &quot;
  dip=&quot;$(normalize_ip_input &quot;$dip&quot;)&quot;
  [[ -z &quot;$dip&quot; ]] &amp;&amp; { print -r -- &quot;[SKIP] No IP entered.&quot;; return 0; }
  if ! is_valid_ip &quot;$dip&quot;; then
    print -r -- &quot;[ERROR] Invalid IP: $dip&quot;
    SESSION_ERROR=1
    return 0
  fi
  read -r &quot;dport?Port [default $DEFAULT_PORT]: &quot;
  dport=&quot;${dport:-$DEFAULT_PORT}&quot;
  if ! is_valid_port &quot;$dport&quot;; then
    print -r -- &quot;[ERROR] Invalid port: $dport (use 1-65535)&quot;
    SESSION_ERROR=1
    return 0
  fi
  print -r -- &quot;[STEP] adb disconnect ${dip}:${dport}&quot;
  if adb disconnect &quot;${dip}:${dport}&quot;; then
    print -r -- &quot;[OK] Disconnected ${dip}:${dport}&quot;
  else
    print -r -- &quot;[ERROR] adb disconnect ${dip}:${dport} failed.&quot;
    SESSION_ERROR=1
  fi
}

disconnect_done() {
  print
  print -r -- &quot;=== Devices now ===&quot;
  adb devices -l || print -r -- &quot;[ERROR] adb devices -l failed.&quot;
  if [[ &quot;$SESSION_ERROR&quot; == &quot;1&quot; ]]; then
    print -r -- &quot;[SUMMARY] Disconnect finished with errors.&quot;
  else
    print -r -- &quot;[SUMMARY] Disconnect finished.&quot;
  fi
}

disconnect_menu() {
  local -a wifi=()
  local adb_line dev_serial dev_state count=0 choice choice_lc manual n target

  print
  print -r -- &quot;=== Wi-Fi / TCP devices (IP:port) ===&quot;

  while IFS= read -r adb_line || [[ -n &quot;$adb_line&quot; ]]; do
    parse_adb_device_line &quot;$adb_line&quot;
    dev_serial=&quot;$PARSED_SERIAL&quot;
    dev_state=&quot;$PARSED_STATE&quot;
    [[ -z &quot;$dev_serial&quot; ]] &amp;&amp; continue
    [[ &quot;$dev_serial&quot; != *:* ]] &amp;&amp; continue
    [[ &quot;$dev_state&quot; == &quot;offline&quot; ]] &amp;&amp; continue
    wifi+=(&quot;$dev_serial&quot;)
    (( ++count ))
    print -r -- &quot;  [$count] $dev_serial  ($dev_state)&quot;
  done &lt; &lt;(adb devices 2&gt;/dev/null | tail -n +2)

  if [[ $count -eq 0 ]]; then
    print -r -- &quot;[INFO] No Wi-Fi devices in list.&quot;
    print -r -- &quot;       USB serial devices are not disconnected with adb disconnect.&quot;
    print
    read -r &quot;manual?Disconnect by IP manually? [Y/n]: &quot;
    if [[ -z &quot;$manual&quot; || &quot;${(L)manual}&quot; == &quot;y&quot; ]]; then
      disconnect_manual
    fi
    disconnect_done
    return 0
  fi

  print
  print -r -- &quot;  [A] Disconnect ALL Wi-Fi devices&quot;
  print -r -- &quot;  [M] Disconnect by typing IP:port manually&quot;
  print -r -- &quot;  [B] Back&quot;
  print
  read -r &quot;choice?Select number, A, M, or B: &quot;
  choice_lc=&quot;${(L)choice}&quot;
  if [[ &quot;$choice_lc&quot; == &quot;b&quot; ]]; then
    disconnect_done
    return 0
  fi

  if [[ &quot;$choice_lc&quot; == &quot;a&quot; ]]; then
    print; print -r -- &quot;[STEP] adb disconnect  (all TCP/IP)&quot;
    if adb disconnect; then
      print -r -- &quot;[OK] Disconnected all TCP/IP devices.&quot;
    else
      print -r -- &quot;[ERROR] adb disconnect failed.&quot;
      SESSION_ERROR=1
    fi
    disconnect_done
    return 0
  fi

  if [[ &quot;$choice_lc&quot; == &quot;m&quot; ]]; then
    disconnect_manual
    disconnect_done
    return 0
  fi

  for n in ${=choice}; do
    if [[ &quot;$n&quot; =~ '^[0-9]+$' ]] &amp;&amp; (( n &gt;= 1 &amp;&amp; n &lt;= count )); then
      target=&quot;${wifi[$(( n - 1 ))]}&quot;
      print; print -r -- &quot;[STEP] adb disconnect $target&quot;
      if adb disconnect &quot;$target&quot;; then
        print -r -- &quot;[OK] Disconnected $target&quot;
      else
        print -r -- &quot;[ERROR] Failed: $target&quot;
        SESSION_ERROR=1
      fi
    else
      print -r -- &quot;[ERROR] Invalid selection: $n&quot;
      SESSION_ERROR=1
    fi
  done

  disconnect_done
}

manage_saved() {
  local mchoice deln i

  print
  load_saved_list
  if [[ $SCOUNT -eq 0 ]]; then
    print -r -- &quot;[INFO] No saved devices in $SAVED_FILE&quot;
    return 0
  fi

  print -r -- &quot;=== Saved devices ===&quot;
  for (( i = 0; i &lt; SCOUNT; i++ )); do
    print -r -- &quot;  [$(( i + 1 ))] ${SLB[i]}  ${SIP[i]}:${SPT[i]}  serial:${SSR[i]}&quot;
  done
  print -r -- &quot;  [D] Delete one&quot;
  print -r -- &quot;  [C] Clear ALL saved&quot;
  print -r -- &quot;  [B] Back&quot;
  print
  read -r &quot;mchoice?Choice: &quot;

  case &quot;${(L)mchoice}&quot; in
    b) return 0 ;;
    c) rm -f &quot;$SAVED_FILE&quot;; print -r -- &quot;[OK] Cleared saved list.&quot; ;;
    d)
      read -r &quot;deln?Number to delete: &quot;
      delete_saved_entry &quot;$deln&quot;
      ;;
    *) print -r -- &quot;[ERROR] Invalid choice.&quot; ;;
  esac
}

show_menu() {
  local menu

  print -r -- &quot;--------------------------------------------&quot;
  print -r -- &quot;  [C] Connect over Wi-Fi (USB needed once)&quot;
  print -r -- &quot;  [S] Connect from saved IP (no USB)&quot;
  print -r -- &quot;  [D] Disconnect Wi-Fi device(s)&quot;
  print -r -- &quot;  [L] List devices (detailed)&quot;
  print -r -- &quot;  [X] Manage saved devices&quot;
  print -r -- &quot;  [E] Exit&quot;
  print -r -- &quot;--------------------------------------------&quot;
  read -r &quot;menu?Choose C / S / D / L / X / E: &quot;

  case &quot;${(L)menu}&quot; in
    c) run_connect ;;
    s) connect_from_saved ;;
    d) disconnect_menu ;;
    l) print; adb devices -l || print -r -- &quot;[ERROR] adb devices -l failed.&quot;; print ;;
    x) manage_saved ;;
    e) pause_before_close; exit 0 ;;
    *) print -r -- &quot;[ERROR] Invalid choice: $menu&quot; ;;
  esac
}

main_menu() {
  while true; do
    clear 2&gt;/dev/null || true
    SESSION_ERROR=0
    print -r -- &quot;============================================&quot;
    print -r -- &quot;  ADB Wi-Fi Connect (auto IP)&quot;
    print -r -- &quot;============================================&quot;
    print
    if [[ -f &quot;$SAVED_FILE&quot; ]]; then
      print -r -- &quot;Saved list: $SAVED_FILE&quot;
    else
      print -r -- &quot;Saved list: (none yet)&quot;
    fi
    print

    if ! ensure_adb; then
      print -r -- &quot;[ERROR] adb not found.&quot;
      print -r -- &quot;        Add Android SDK platform-tools to PATH.&quot;
      print -r -- &quot;        Example: \$HOME/Library/Android/sdk/platform-tools&quot;
      print -r -- &quot;        Or install: brew install android-platform-tools&quot;
      show_menu
      continue
    fi

    print -r -- &quot;=== Current devices ===&quot;
    if ! adb devices; then
      print -r -- &quot;[ERROR] adb devices failed.&quot;
      show_menu
      continue
    fi
    print
    show_menu
  done
}

if (( ${#} &gt; 0 )); then
  print -r -- &quot;[WARN] This script is interactive. Double-click adb_wifi_connect.command in Finder.&quot;
fi

main_menu || {
  print -r -- &quot;[FATAL] Unexpected error (exit $?).&quot;
  pause_before_close
  exit 1
}

